---

## 수정 항목 (우선순위순)

### 사전작업: `src/core/utils.js` 신규 생성
- `safeName()` 공통화 기반 파일
```js
'use strict';
function safeName(name) {
  return String(name ?? 'var').replace(/[^\w]/g, '_');
}
module.exports = { safeName };
```

---

### [Critical] 1. `readBody()` 타임아웃 미설정
**파일**: `src/api/server.js`
**문제**: 클라이언트가 연결 끊지 않으면 무한 대기 (SlowLoris 취약)
**수정**: 5초 타임아웃 + done 플래그 + `req.destroy()` 추가

```js
const BODY_TIMEOUT_MS = 5_000;

function readBody(req) {
  return new Promise((resolve, reject) => {
    let data = '', done = false;
    const timer = setTimeout(() => {
      if (!done) { done = true; req.destroy(); reject(new Error('요청 타임아웃 (5초 초과)')); }
    }, BODY_TIMEOUT_MS);
    const finish = (fn) => (...args) => { if (done) return; done = true; clearTimeout(timer); fn(...args); };
    req.on('data', chunk => {
      data += chunk;
      if (data.length > 1_000_000) { done = true; clearTimeout(timer); req.destroy(); reject(new Error('너무 큰 요청')); }
    });
    req.on('end',  finish(() => { try { resolve(JSON.parse(data)); } catch (e) { reject(e); } }));
    req.on('error', finish(reject));
  });
}
```
**검증**: 수동 curl 테스트 (기존 테스트 영향 없음)

