topologicalSort() {
  const visited    = new Set();
  const onStack    = new Set(); // 사이클 감지용
  const cycleNodes = new Set(); // 사이클에 포함된 노드 기록
  const order      = [];

  const visit = (nodeId) => {
    if (visited.has(nodeId)) return;
    if (onStack.has(nodeId)) {
      // 사이클 감지: 경고 기록 후 건너뜀 (순환 의존)
      cycleNodes.add(nodeId);
      return;
    }
    onStack.add(nodeId);
    this.incomingEdges(nodeId).forEach(e => visit(e.from.nodeId));
    onStack.delete(nodeId);
    visited.add(nodeId);
    order.push(nodeId);
  };

  this.nodes.forEach(n => visit(n.id));

  if (cycleNodes.size > 0) {
    console.warn(`[Graph] 사이클 감지: [${[...cycleNodes].join(', ')}] — 해당 노드는 컴파일에서 누락됩니다.`);
  }

