/**
 * FreeWire Agent — Tool 정의 + executeTool() 래퍼
 *
 * Claude API tools 파라미터에 등록할 5개 도구:
 *   freewire_generate, freewire_compile, freewire_execute,
 *   freewire_evaluate, freewire_preview
 *
 * executeTool(): HTTP → 실패 시 직접 모듈 호출 fallback
 */

'use strict';

const http = require('http');

// ─── Tool 정의 (Claude API tools 파라미터용) ───────────────────

const TOOLS = [
  {
    name: 'freewire_generate',
    description: '자연어 프롬프트를 받아 FreeWire 노드 그래프 JSON을 생성합니다.',
    input_schema: {
      type: 'object',
      properties: {
        prompt: {
          type: 'string',
          description: '생성할 UI를 설명하는 자연어 (예: "로그인 폼", "카운터 앱")',
        },
      },
      required: ['prompt'],
    },
  },
  {
    name: 'freewire_compile',
    description: 'FreeWire 그래프 JSON을 FreeLang .free 코드로 컴파일합니다.',
    input_schema: {
      type: 'object',
      properties: {
        graph: {
          type: 'object',
          description: 'FreeWire 그래프 JSON { nodes, edges }',
        },
      },
      required: ['graph'],
    },
  },
  {
    name: 'freewire_execute',
    description: 'FreeWire 그래프를 실행하여 HTML/CSS/JS 결과물을 반환합니다.',
    input_schema: {
      type: 'object',
      properties: {
        graph: {
          type: 'object',
          description: 'FreeWire 그래프 JSON',
        },
      },
      required: ['graph'],
    },
  },
  {
    name: 'freewire_evaluate',
    description: '그래프가 목표를 얼마나 충족하는지 0-100점으로 평가합니다. 위반 사항과 수정 힌트를 반환합니다.',
    input_schema: {
      type: 'object',
      properties: {
        graph: {
          type: 'object',
          description: 'FreeWire 그래프 JSON',
        },
        goal: {
          type: 'string',
          description: '사용자의 원래 의도/목표 텍스트',
        },
      },
      required: ['graph', 'goal'],
    },
  },
  {
    name: 'freewire_preview',
    description: '그래프의 HTML 미리보기 URL을 생성합니다.',
    input_schema: {
      type: 'object',
      properties: {
        graph: {
          type: 'object',
          description: 'FreeWire 그래프 JSON',
        },
      },
      required: ['graph'],
    },
  },
];

// ─── HTTP → 직접 호출 매핑 ────────────────────────────────────

const TOOL_HTTP_PATH = {
  freewire_generate: '/api/ai-generate',
  freewire_compile:  '/api/compile',
  freewire_execute:  '/api/execute',
  freewire_preview:  '/api/preview',
  // freewire_evaluate: 서버 엔드포인트 없음 → 항상 directCall
};

/**
 * Tool 실행 진입점
 * 1) HTTP POST 시도 → 2) 실패 시 직접 모듈 호출
 */
async function executeTool(name, input, options = {}) {
  const { serverUrl = 'http://localhost:4010', apiKey } = options;

  // freewire_evaluate는 서버 엔드포인트 없음
  if (name === 'freewire_evaluate') {
    return await _directCall(name, input, options);
  }

  try {
    const path = TOOL_HTTP_PATH[name];
    if (!path) throw new Error(`알 수 없는 tool: ${name}`);
    const body = _buildHttpBody(name, input, apiKey);
    return await _httpPost(serverUrl, path, body);
  } catch (_) {
    return await _directCall(name, input, options);
  }
}

function _buildHttpBody(name, input, apiKey) {
  switch (name) {
    case 'freewire_generate': return { prompt: input.prompt, apiKey };
    case 'freewire_compile':  return { graph: input.graph };
    case 'freewire_execute':  return { graph: input.graph };
    case 'freewire_preview':  return { graph: input.graph };
    default: return input;
  }
}

// ─── 직접 모듈 호출 ──────────────────────────────────────────

async function _directCall(name, input, options = {}) {
  switch (name) {
    case 'freewire_generate': {
      const { aiGenerateGraph } = require('../api/ai-graph-generator');
      const result = await aiGenerateGraph(input.prompt, options.apiKey || null);
      return { graph: result.graph, label: result.label, source: result.source, nodeCount: result.nodeCount };
    }

    case 'freewire_compile': {
      const { GraphCompiler } = require('../compiler/graph-compiler');
      const compiler = new GraphCompiler();
      const graph = require('../core/graph').Graph.fromJSON(input.graph);
      return compiler.compile(graph);
    }

    case 'freewire_execute': {
      const { GraphCompiler } = require('../compiler/graph-compiler');
      const { FreeExecutor }  = require('../api/free-executor');
      const { Graph }         = require('../core/graph');
      const compiler = new GraphCompiler();
      const graph    = Graph.fromJSON(input.graph);
      const compiled = compiler.compile(graph);
      if (compiled.errors && compiled.errors.length > 0) {
        return { html: '', css: '', js: '', errors: compiled.errors };
      }
      const executor = new FreeExecutor();
      return executor.execute(compiled.code, input.graph);
    }

    case 'freewire_evaluate': {
      const { IntentEvaluator } = require('../intent/evaluator');
      const nodesMap = _graphNodesToMap(input.graph?.nodes);
      const wiresMap = _graphEdgesToMap(input.graph?.edges);
      const evaluator = new IntentEvaluator();
      const report = evaluator.evaluate(nodesMap, wiresMap, input.goal || '');
      return {
        score:      report.score,
        passed:     report.passed,
        violations: (report.violations || []).map(v => ({
          type:        v.type,
          message:     v.message,
          severity:    v.severity,
          repairHint:  v.repairHint,
        })),
        summary: report.summary,
      };
    }

    case 'freewire_preview': {
      return { previewUrl: null, fallback: true };
    }

    default:
      throw new Error(`알 수 없는 tool: ${name}`);
  }
}

// ─── 헬퍼: 배열 → Map 변환 ───────────────────────────────────

function _graphNodesToMap(nodesArray) {
  const map = new Map();
  for (const node of (nodesArray || [])) map.set(node.id, node);
  return map;
}

function _graphEdgesToMap(edgesArray) {
  const map = new Map();
  for (const edge of (edgesArray || [])) {
    map.set(edge.id || `e-${map.size}`, edge);
  }
  return map;
}

// ─── HTTP POST 헬퍼 ───────────────────────────────────────────

function _httpPost(serverUrl, path, body, timeoutMs = 5000) {
  return new Promise((resolve, reject) => {
    const payload = JSON.stringify(body);
    let hostname, port;
    try {
      const u = new URL(serverUrl);
      hostname = u.hostname;
      port     = u.port || 80;
    } catch (_) {
      hostname = 'localhost';
      port     = 4010;
    }

    const req = http.request({
      hostname,
      port,
      path,
      method:  'POST',
      headers: {
        'Content-Type':   'application/json',
        'Content-Length': Buffer.byteLength(payload),
      },
    }, res => {
      let data = '';
      res.on('data', chunk => data += chunk);
      res.on('end', () => {
        try { resolve(JSON.parse(data)); }
        catch (e) { reject(new Error('JSON 파싱 실패')); }
      });
    });

    req.setTimeout(timeoutMs, () => { req.destroy(); reject(new Error('HTTP 타임아웃')); });
    req.on('error', reject);
    req.write(payload);
    req.end();
  });
}

module.exports = { TOOLS, executeTool, _graphNodesToMap, _graphEdgesToMap };

