            tool_use_id: block.id,
            content:     JSON.stringify(result),
          });
        }

        messages.push({ role: 'assistant', content: response.content });
        messages.push({ role: 'user',      content: toolResults });
        turn++;
      } else {
        // 예상치 못한 stop_reason
        break;
      }
    }

    return {
      html:       agentState.html,
      css:        agentState.css,
      js:         agentState.js,
      graph:      agentState.graph,
      score:      agentState.score,
      turns:      turn,
      previewUrl: agentState.previewUrl,
      fallback:   false,
    };
  }

  /**
   * API 키 없을 때: 직접 모듈 파이프라인 실행
   * generate(규칙기반) → evaluate → compile → execute
   */
  async _fallbackRun(userRequest) {
    const { aiGenerateGraph }  = require('../api/ai-graph-generator');
    const { IntentEvaluator }  = require('../intent/evaluator');
    const { GraphCompiler }    = require('../compiler/graph-compiler');
    const { FreeExecutor }     = require('../api/free-executor');
    const { Graph }            = require('../core/graph');
    const { _graphNodesToMap, _graphEdgesToMap } = require('./tools');

    // 1) 규칙 기반 그래프 생성
    const generated = await aiGenerateGraph(userRequest, null);
    const graph = generated.graph || { nodes: [], edges: [] };

    // 2) 평가
    const nodesMap = _graphNodesToMap(graph.nodes);
    const wiresMap = _graphEdgesToMap(graph.edges);
    const evaluator = new IntentEvaluator();
    const report = evaluator.evaluate(nodesMap, wiresMap, userRequest);

    // 3) 컴파일 + 실행
    let html = '', css = '', js = '';
    try {
      const graphObj = Graph.fromJSON(graph);
      const compiler = new GraphCompiler();
      const compiled = compiler.compile(graphObj);
      if (!compiled.errors || compiled.errors.length === 0) {
        const executor = new FreeExecutor();
        const executed = executor.execute(compiled.code, graph);
        html = executed.html || '';
        css  = executed.css  || '';
        js   = executed.js   || '';
      }
    } catch (_) {}

    return {
      html,
      css,
      js,
      graph,
      score:      report.score,
      turns:      0,
      previewUrl: null,
      fallback:   true,
    };
  }
}

module.exports = { FreeWireAgent };

