/**
 * FreeWire Agent — CLI 진입점
 *
 * 사용법:
 *   node src/agent/run-agent.js "로그인 폼 만들어줘"
 *
 * 환경변수:
 *   ANTHROPIC_API_KEY   — Claude API 키
 *   FREEWIRE_SERVER     — API 서버 URL (기본: http://localhost:4010)
 *   MAX_TURNS           — 최대 루프 횟수 (기본: 10)
 *   TARGET_SCORE        — 목표 점수 (기본: 80)
 *
 * 출력:
 *   agent-output/result.html  — 완전한 HTML 문서
 *   agent-output/result.json  — 전체 AgentResult
 */

'use strict';

const fs   = require('fs');
const path = require('path');
const { FreeWireAgent } = require('./freewire-agent');

async function main() {
  const userRequest = process.argv[2];
  if (!userRequest) {
    console.error('사용법: node src/agent/run-agent.js "요구사항"');
    console.error('예시:   node src/agent/run-agent.js "카운터 앱 만들어줘"');
    process.exit(1);
  }

  console.log(`\n[FreeWire Agent] 시작`);
  console.log(`요구사항: "${userRequest}"`);
  console.log(`모드: ${process.env.ANTHROPIC_API_KEY ? 'Claude API' : '규칙 기반 폴백'}\n`);

  const agent = new FreeWireAgent({
    maxTurns:    parseInt(process.env.MAX_TURNS)    || 10,
    targetScore: parseInt(process.env.TARGET_SCORE) || 80,
    apiKey:      process.env.ANTHROPIC_API_KEY      || null,
    serverUrl:   process.env.FREEWIRE_SERVER        || 'http://localhost:4010',
  });

  let result;
  try {
    result = await agent.run(userRequest);
  } catch (e) {
    console.error('[Agent] 실행 실패:', e.message);
    process.exit(1);
  }

  console.log(`\n[결과]`);
  console.log(`  점수:   ${result.score}/100`);
  console.log(`  턴 수:  ${result.turns}`);
  console.log(`  모드:   ${result.fallback ? '폴백' : 'Claude Tool Use'}`);
  console.log(`  노드:   ${result.graph?.nodes?.length ?? 0}개`);
  console.log(`  HTML:   ${result.html?.length ?? 0}자`);

  // agent-output/ 디렉토리 생성
  const outDir = path.join(__dirname, '../../agent-output');
  if (!fs.existsSync(outDir)) fs.mkdirSync(outDir, { recursive: true });

  // result.html — 완전한 HTML 문서
  const fullHtml = _buildFullHtml(result, userRequest);
  fs.writeFileSync(path.join(outDir, 'result.html'), fullHtml, 'utf8');

  // result.json
  fs.writeFileSync(
    path.join(outDir, 'result.json'),
    JSON.stringify(result, null, 2),
    'utf8'
  );

  console.log(`\n[저장]`);
  console.log(`  ${path.join(outDir, 'result.html')}`);
  console.log(`  ${path.join(outDir, 'result.json')}`);
}

function _buildFullHtml(result, title) {
  return `<!DOCTYPE html>
<html lang="ko">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>${_esc(title)}</title>
  <style>
    * { box-sizing: border-box; margin: 0; padding: 0; }
    body { font-family: -apple-system, sans-serif; padding: 24px; background: #f9fafb; }
    ${result.css || ''}
  </style>
</head>
<body>
  ${result.html || '<p>내용 없음</p>'}
  <script>
    ${result.js || ''}
  </script>
  <div style="position:fixed;bottom:12px;right:12px;font-size:11px;color:#9ca3af;background:#fff;padding:4px 8px;border-radius:4px;border:1px solid #e5e7eb;">
    FreeWire Agent · 점수 ${result.score}/100
  </div>
</body>
</html>`;
}

function _esc(str) {
  return String(str ?? '')
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;');
}

main().catch(e => { console.error(e); process.exit(1); });

